style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* Apply to all elements */
    * {
        font-family: 'Minecraft', sans-serif !important;
        color: #222 !important;
        background-color: #f0f0f0 !important;
    }

    /* Links styling */
    a {
        color: #0077cc !important;
        text-decoration: none !important;
    }

    /* Headings */
    h1, h2, h3, h4, h5, h6 {
        font-family: 'Minecraft', sans-serif !important;
    }
}
